package org.example.spotifymixer.engine;
import org.junit.Test;import static org.junit.Assert.*;import java.io.*;import java.util.*;import org.jf.dexlib2.*;import org.jf.dexlib2.iface.*;import org.jf.dexlib2.iface.instruction.*;import org.jf.dexlib2.iface.reference.*;import org.jf.dexlib2.immutable.*;import org.jf.dexlib2.immutable.instruction.*;import org.jf.dexlib2.dexbacked.*;import org.jf.dexlib2.writer.io.*;import org.jf.dexlib2.writer.pool.*;
public class ThemeHookTest {
 private byte[] fixture(String name)throws Exception{Method method=new ImmutableMethod(name,"K",Collections.singletonList(new ImmutableMethodParameter("J",Collections.emptySet(),null)),"I",9,Collections.emptySet(),Collections.emptySet(),new ImmutableMethodImplementation(30,Arrays.asList(new ImmutableInstruction31i(Opcode.CONST,27,0xff121212),new ImmutableInstruction11x(Opcode.RETURN,27)),Collections.emptyList(),Collections.emptyList()));ClassDef cls=new ImmutableClassDef(name,1,"Ljava/lang/Object;",Collections.emptyList(),null,Collections.emptySet(),Collections.emptyList(),Collections.singletonList(method));MemoryDataStore out=new MemoryDataStore();DexPool.writeTo(out,new ImmutableDexFile(Opcodes.forApi(24),Collections.singletonList(cls)));return out.getData();}
 @Test public void relocatesAndMapsActualReturnRegister()throws Exception{byte[][] out=ThemeHook.patch(fixture("Lp/k5k1;"));assertTrue(new DexBackedDexFile(Opcodes.forApi(24),out[0]).getClasses().isEmpty());ClassDef cls=new DexBackedDexFile(Opcodes.forApi(24),out[1]).getClasses().iterator().next();Method m=cls.getMethods().iterator().next();assertEquals(30,m.getImplementation().getRegisterCount());Iterator<? extends Instruction> i=m.getImplementation().getInstructions().iterator();assertEquals(Opcode.CONST,i.next().getOpcode());Instruction call=i.next();assertEquals(27,((RegisterRangeInstruction)call).getStartRegister());assertEquals("mapColor",((MethodReference)((ReferenceInstruction)call).getReference()).getName());assertEquals(Opcode.MOVE_RESULT,i.next().getOpcode());assertEquals(Opcode.RETURN,i.next().getOpcode());}
 @Test(expected=IOException.class)public void rejectsWrongNativeContract()throws Exception{ThemeHook.patch(fixture("Lp/unknown;"));}
}
